import sys; sys.path.insert(0,'/home/claude/skripty')
from stranka import zapis
O='/home/claude/dokuio.com/src/obsah/lv/'
P=lambda n,p:{'nazev':n,'popis':p}
K3=[('Aizpildiet datus','Ko nezināt, izlaidiet – paliks līnija aizpildīšanai ar roku.'),('Pārbaudiet tekstu','Katru rindkopu varat rediģēt.'),('Lejupielādējiet un parakstiet','PDF vai Word, bez maksas.')]
PRIV=('Vai jūs saglabājat manus datus?','Nē. Dokuments tiek izveidots tieši jūsu pārlūkā, dati netiek sūtīti uz serveri.')
CLP='Paraugs balstās uz Civillikuma noteikumiem.'
def d(slug, ident, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'Citi dokumenti, arī bez maksas.'}
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(title.replace('{rok}','2026'))>70: print('TITLE',slug,len(title.replace('{rok}','2026')))
    if not 30<=len(vd)<=170: print('VD',slug,len(vd))
    if len(vt)>70: print('VT',slug,len(vt))
    for w in ('paraugs','PDF','bez maksas'): assert w in title, (slug,w)
    zapis(O+slug+'.ts','lv',slug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},kat,landing,{'title':vt,'description':vd,'podnadpis':'Bez maksas · rezultāts PDF un Word formātā · aizņem dažas minūtes'})

